successful_read_commands.command:
/bin/zsh -lc "node --input-type=module <<'NODE'
import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { parseDocument } from './scripts/vendor/yaml.mjs';
mkdirSync('drafts', { recursive: true });
const source = readFileSync('DESIGN.md', 'utf8');
const design = parseDocument(source.split(/"'^---'"\\s*"'$/m)[1]).toJS();
const css = ['"'/* Derived from root DESIGN.md for this disposable fixture. */', ':root {'];
for (const [name, value] of Object.entries(design.colors)) css.push("'`  --design-color-${name}: ${value};`);
for (const [name, value] of Object.entries(design.typography)) {
  for (const [property, val] of Object.entries(value)) css.push(`  --design-${name}-${property.replace(/[A-Z]/g, x => '"'-' + x.toLowerCase())}: "'${val};`);
}
css.push('"'}');
writeFileSync('drafts/design-roles.css', css.join('\\n') + '\\n');
copyFileSync('.template-spec/design/tokens/variables.css', 'drafts/tokens.css');
const records = JSON.parse(readFileSync('fixture/data.json', 'utf8'));
writeFileSync('drafts/scenarios.js', "'`/* Exact fixture records; ordinary script supports offline file opening. */'"\\nwindow.FIXTURE_DATA = "'${JSON.stringify(records, null, 2)};'"\\nwindow.PROTOTYPE_SCENARIOS = Object.freeze({\\n  primary: { label: '正常查询', canViewDetails: true },\\n  'no-permission': { label: '无详情权限', canViewDetails: false }\\n});\\n"'`);
const sha = p => '"'sha256:' + createHash('sha256').update(readFileSync(p)).digest('hex');
const manifest = {
  schema_version: 4, feature: 'list-detail-fixture', pattern: 'workbench',
  prototype_profile: 'H2', profile_kind: 'flow-review', component_basis: 'html-css-js', runtime_build_required: false, entry: 'index.html',
  design_source: { path: 'DESIGN.md', digest: sha('DESIGN.md') },
  token_source: { path: '.template-spec/design/tokens/variables.css', digest: sha('drafts/tokens.css') },
  input_sources: Object.fromEntries(['fixture/brief.md', 'fixture/data.json', 'CONTEXT.md', '.template-spec/design/tokens/tokens.default.json'].map(p => [p, sha(p)])),
  fixture_only: true, delivery_contract: 'offline-html-v1', browser_verification: 'not-run', user_confirmation: 'not-requested', files: {}
};
writeFileSync('drafts/yss-prototype-adapter.json', JSON.stringify(manifest, null, 2) + '\\n');
console.log('Created local token copies, exact fixture data, and draft resource manifest.');
NODE"
